import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");

  // Act
  const response = await member.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const cookies = response
    .headersArray()
    .filter((h) => h.name.toLowerCase() === "set-cookie")
    .map((h) => h.value);
  const session = cookies.find((c) => c.startsWith("session="));
  expect(session, `Set-Cookie headers: ${JSON.stringify(cookies)}`).toBeDefined();
  // A cleared cookie has an empty value and expires immediately.
  expect(session, `Set-Cookie headers: ${JSON.stringify(cookies)}`).toMatch(/^session=(""|);/);
  expect(session?.toLowerCase(), `Set-Cookie headers: ${JSON.stringify(cookies)}`).toContain("max-age=0");
});
